      backup_text =
        "# Garden Spirit #\n\
         # A small spirit that tends your garden #\n\n\
         type Stat = Int in  # 0-100 range #\n\n\
         type Stats = (\n\
         hunger = Stat,     # 0 = starving, 100 = full #\n\
         happiness = Stat,  # 0 = miserable, 100 = ecstatic #\n\
         energy = Stat,     # 0 = exhausted, 100 = hyperactive #\n\
         health = Stat      # 0 = fading, 100 = vibrant #\n\
         ) in\n\n\
         type Evolution =\n\
         + Seedling      # Newly sprouted #\n\
         + Sprout      # Growing, unpredictable #\n\
         + Bloom     # In full bloom #\n\
         + Elder    # Ancient and wise #\n\
         + Wilted     # Neglected, withering #\n\
         in\n\n\
         type Personality =\n\
         + Cheerful\n\
         + Grumpy\n\
         + Anxious\n\
         + Balanced\n\
         in\n\n\
         type Memory = (\n\
         timesFed = Int,\n\
         timesPlayed = Int,\n\
         timesSlept = Int,\n\
         timesNeglected = Int\n\
         ) in\n\n\
         type Model = (\n\
         stats = Stats,\n\
         evolution = Evolution,\n\
         personality = Personality,\n\
         memory = Memory,\n\
         age = Int           # Time ticks elapsed #\n\
         ) in\n\n\
         type Action =\n\
         + Feed              # Reduces hunger, slight energy boost #\n\
         + Play              # Increases happiness, costs energy #\n\
         + Sleep             # Restores energy, slight health boost #\n\
         + Mend            # Fixes health issues #\n\
         + TimeTick          # Time passes, stats decay #\n\
         in\n\n\
         # Utility: clamp value between 0 and 100 #\n\
         let clamp : Int -> Int =\n\
         fun x ->\n\
         if x < 0 then 0\n\
         else if x > 100 then 100\n\
         else x\n\
         in\n\n\
         # Initial state #\n\
         let init: Model = (\n\
         stats = (\n\
         hunger = 50,\n\
         happiness = 50,\n\
         energy = 50,\n\
         health = 100\n\
         ),\n\
         evolution = Seedling,\n\
         personality = Balanced,\n\
         memory = (\n\
         timesFed = 0,\n\
         timesPlayed = 0,\n\
         timesSlept = 0,\n\
         timesNeglected = 0\n\
         ),\n\
         age = 0\n\
         ) in\n\n\
         # Calculate stat decay based on current stats and interactions #\n\
         let decayStats : Stats -> Stats =\n\
         fun s ->\n\
         let hungerDecay = 5 in\n\
         let happinessDecay =\n\
         if s.hunger < 30 then 8  # Hungry makes mood worse #\n\
         else 3\n\
         in\n\
         let energyDecay = 2 in\n\
         let healthDecay =\n\
         if s.energy < 20 then 5   # Exhaustion hurts health #\n\
         else if s.hunger < 20 then 3  # Starvation hurts health #\n\
         else 0\n\
         in\n\
         (\n\
         hunger = clamp(s.hunger - hungerDecay),\n\
         happiness = clamp(s.happiness - happinessDecay),\n\
         energy = clamp(s.energy - energyDecay),\n\
         health = clamp(s.health - healthDecay)\n\
         )\n\
         in\n\n\
         # Determine personality based on memory #\n\
         let calcPersonality : Memory -> Personality =\n\
         fun m ->\n\
         let careScore = m.timesFed + m.timesPlayed + m.timesSlept in\n\
         let neglectScore = m.timesNeglected in\n\
         if neglectScore > careScore then Grumpy\n\
         else if m.timesPlayed > m.timesFed + m.timesSlept then Cheerful\n\
         else if m.timesNeglected > 5 then Anxious\n\
         else Balanced\n\
         in\n\n\
         # Determine evolution based on age and care quality #\n\
         let calcEvolution : (Int, Memory) -> Evolution =\n\
         fun (age, m) ->\n\
         let careScore = m.timesFed + m.timesPlayed + m.timesSlept in\n\
         let neglectScore = m.timesNeglected in\n\
         if age < 10 then Seedling\n\
         else if age < 25 then Sprout\n\
         else if careScore > neglectScore * 3 then Elder\n\
         else if neglectScore > careScore then Wilted\n\
         else Bloom\n\
         in\n\n\
         # Check if stats indicate neglect (any stat critically low) #\n\
         let isNeglected : Stats -> Bool =\n\
         fun s ->\n\
         s.hunger < 15 || s.happiness < 15 || s.energy < 10 || s.health < 20\n\
         in\n\n\
         # Update memory based on action #\n\
         let updateMemory : (Memory, Action, Stats) -> Memory =\n\
         fun (m, action, stats) ->\n\
         case action\n\
         | Feed => (m.timesFed + 1, m.timesPlayed, m.timesSlept, \
         m.timesNeglected)\n\
         | Play => (m.timesFed, m.timesPlayed + 1, m.timesSlept, \
         m.timesNeglected)\n\
         | Sleep => (m.timesFed, m.timesPlayed, m.timesSlept + 1, \
         m.timesNeglected)\n\
         | Mend => m\n\
         | TimeTick =>\n\
         if isNeglected(stats)\n\
         then (m.timesFed, m.timesPlayed, m.timesSlept, m.timesNeglected + 1)\n\
         else m\n\
         end\n\
         in\n\n\
         # Apply an action to stats #\n\
         let applyAction : (Stats, Action, Personality) -> Stats =\n\
         fun (s, action, personality) ->\n\
         # Personality affects action effectiveness #\n\
         let bonus = case personality\n\
         | Cheerful => 5\n\
         | Grumpy => -5\n\
         | Anxious => -2\n\
         | Balanced => 0\n\
         end\n\
         in\n\
         case action\n\
         | Feed =>\n\
         (\n\
         hunger = clamp(s.hunger + 30 + bonus),\n\
         happiness = clamp(s.happiness + 5),\n\
         energy = clamp(s.energy + 10),\n\
         health = s.health\n\
         )\n\
         | Play =>\n\
         if s.energy < 20\n\
         then # Too tired to play effectively #\n\
         (\n\
         hunger = s.hunger,\n\
         happiness = clamp(s.happiness + 5),\n\
         energy = clamp(s.energy - 5),\n\
         health = s.health\n\
         )\n\
         else\n\
         (\n\
         hunger = clamp(s.hunger - 10),\n\
         happiness = clamp(s.happiness + 25 + bonus),\n\
         energy = clamp(s.energy - 15),\n\
         health = s.health\n\
         )\n\
         | Sleep =>\n\
         (\n\
         hunger = clamp(s.hunger - 5),\n\
         happiness = s.happiness,\n\
         energy = clamp(s.energy + 40 + bonus),\n\
         health = clamp(s.health + 5)\n\
         )\n\
         | Mend =>\n\
         (\n\
         hunger = s.hunger,\n\
         happiness = clamp(s.happiness - 10),  # Mending is uncomfortable #\n\
         energy = s.energy,\n\
         health = clamp(s.health + 35 + bonus)\n\
         )\n\
         | TimeTick => decayStats(s)\n\
         end\n\
         in\n\n\
         # Main update function #\n\
         let update : (Model, Action) -> Model =\n\
         fun (m, action) ->\n\
         let newStats = applyAction(m.stats, action, m.personality) in\n\
         let newMemory = updateMemory(m.memory, action, m.stats) in\n\
         let newAge = case action\n\
         | TimeTick => m.age + 1\n\
         | _ => m.age\n\
         end\n\
         in\n\
         (\n\
         stats = newStats,\n\
         evolution = calcEvolution(newAge, newMemory),\n\
         personality = calcPersonality(newMemory),\n\
         memory = newMemory,\n\
         age = newAge\n\
         )\n\
         in\n\n\
         # Run multiple actions in sequence #\n\
         let do : (Model, [Action]) -> Model =\n\
         fun (model: Model, actions: [Action]) ->\n\
         fold_left(actions, update, model)\n\
         in\n\n\
         # Generate n TimeTicks (range is inclusive, so use n-1) #\n\
         let timePasses : Int -> [Action] =\n\
         fun n ->\n\
         if n <= 0 then []\n\
         else map(range(1, n), fun _ -> TimeTick)\n\
         in\n\n\
         # ===== TESTS ===== #\n\n\
         # Basic feeding test #\n\
         hint \"feeding increases hunger stat\"\n\
         test\n\
         let m = update(init, Feed) in\n\
         m.stats.hunger > init.stats.hunger\n\
         end;\n\n\
         hint \"feeding also gives small happiness boost\"\n\
         test\n\
         let m = update(init, Feed) in\n\
         m.stats.happiness > init.stats.happiness\n\
         end;\n\n\
         # Playing tests #\n\
         hint \"playing increases happiness when has energy\"\n\
         test\n\
         let m = update(init, Play) in\n\
         m.stats.happiness > init.stats.happiness\n\
         end;\n\n\
         hint \"playing costs energy\"\n\
         test\n\
         let m = update(init, Play) in\n\
         m.stats.energy < init.stats.energy\n\
         end;\n\n\
         hint \"playing when exhausted is less effective\"\n\
         test\n\
         let exhausted = (\n\
         stats = (hunger = 50, happiness = 30, energy = 10, health = 80),\n\
         evolution = Seedling,\n\
         personality = Balanced,\n\
         memory = init.memory,\n\
         age = 0\n\
         ) in\n\
         let m = update(exhausted, Play) in\n\
         # Only +5 happiness instead of +25 #\n\
         m.stats.happiness == 35\n\
         end;\n\n\
         # Sleeping tests #\n\
         hint \"sleeping restores energy\"\n\
         test\n\
         let tired = (\n\
         stats = (hunger = 50, happiness = 50, energy = 30, health = 80),\n\
         evolution = Seedling,\n\
         personality = Balanced,\n\
         memory = init.memory,\n\
         age = 0\n\
         ) in\n\
         let m = update(tired, Sleep) in\n\
         m.stats.energy == 70\n\
         end;\n\n\
         hint \"sleeping improves health slightly\"\n\
         test\n\
         let m = update(init, Sleep) in\n\
         m.stats.health > init.stats.health || m.stats.health == 100\n\
         end;\n\n\
         # Mend tests #\n\
         hint \"mend increases health\"\n\
         test\n\
         let damaged = (\n\
         stats = (hunger = 50, happiness = 50, energy = 50, health = 40),\n\
         evolution = Seedling,\n\
         personality = Balanced,\n\
         memory = init.memory,\n\
         age = 0\n\
         ) in\n\
         let m = update(damaged, Mend) in\n\
         m.stats.health == 75\n\
         end;\n\n\
         hint \"mend is uncomfortable (decreases happiness)\"\n\
         test\n\
         let m = update(init, Mend) in\n\
         m.stats.happiness < init.stats.happiness\n\
         end;\n\n\
         # Time decay tests #\n\
         hint \"time tick reduces hunger\"\n\
         test\n\
         let m = update(init, TimeTick) in\n\
         m.stats.hunger < init.stats.hunger\n\
         end;\n\n\
         hint \"time tick reduces energy\"\n\
         test\n\
         let m = update(init, TimeTick) in\n\
         m.stats.energy < init.stats.energy\n\
         end;\n\n\
         hint \"hunger affects happiness decay rate\"\n\
         test\n\
         let hungry = (\n\
         stats = (hunger = 20, happiness = 50, energy = 50, health = 80),\n\
         evolution = Seedling,\n\
         personality = Balanced,\n\
         memory = init.memory,\n\
         age = 0\n\
         ) in\n\
         let full = (\n\
         stats = (hunger = 80, happiness = 50, energy = 50, health = 80),\n\
         evolution = Seedling,\n\
         personality = Balanced,\n\
         memory = init.memory,\n\
         age = 0\n\
         ) in\n\
         let hungryAfter = update(hungry, TimeTick) in\n\
         let fullAfter = update(full, TimeTick) in\n\
         # Hungry spirit loses more happiness #\n\
         hungryAfter.stats.happiness < fullAfter.stats.happiness\n\
         end;\n\n\
         hint \"exhaustion hurts health\"\n\
         test\n\
         let exhausted = (\n\
         stats = (hunger = 50, happiness = 50, energy = 15, health = 50),\n\
         evolution = Seedling,\n\
         personality = Balanced,\n\
         memory = init.memory,\n\
         age = 0\n\
         ) in\n\
         let m = update(exhausted, TimeTick) in\n\
         m.stats.health < exhausted.stats.health\n\
         end;\n\n\
         # Evolution tests #\n\
         hint \"starts as seedling\"\n\
         test\n\
         init.evolution == Seedling\n\
         end;\n\n\
         hint \"evolves to sprout after age 10\"\n\
         test\n\
         let m = do(init, timePasses(10)) in\n\
         m.evolution == Sprout\n\
         end;\n\n\
         hint \"well-cared-for spirit becomes elder\"\n\
         test\n\
         # Must interleave care with time to avoid neglect #\n\
         # Need age >= 25 and careScore > neglectScore * 3 #\n\
         let wellCared = do(init, [\n\
         # Day 1-5: good care routine (15 care, 10 ticks) #\n\
         Feed, Play, Sleep, TimeTick, TimeTick,\n\
         Feed, Play, Sleep, TimeTick, TimeTick,\n\
         Feed, Play, Sleep, TimeTick, TimeTick,\n\
         Feed, Play, Sleep, TimeTick, TimeTick,\n\
         Feed, Play, Sleep, TimeTick, TimeTick,\n\
         # Day 6-10: continue care (12 care, 15 ticks) #\n\
         Feed, Play, Sleep, TimeTick, TimeTick, TimeTick,\n\
         Feed, Sleep, TimeTick, TimeTick, TimeTick,\n\
         Feed, Play, Sleep, TimeTick, TimeTick, TimeTick,\n\
         Feed, Sleep, TimeTick, TimeTick, TimeTick,\n\
         Feed, Play, Sleep, TimeTick, TimeTick, TimeTick\n\
         ]) in\n\
         # age = 25, careScore = 27 (10 feed + 8 play + 9 sleep), neglectScore \
         = 0 #\n\
         wellCared.evolution == Elder\n\
         end;\n\n\
         # Memory tests #\n\
         hint \"feeding increments timesFed\"\n\
         test\n\
         let m = do(init, [Feed, Feed, Feed]) in\n\
         m.memory.timesFed == 3\n\
         end;\n\n\
         hint \"playing increments timesPlayed\"\n\
         test\n\
         let m = do(init, [Play, Play]) in\n\
         m.memory.timesPlayed == 2\n\
         end;\n\n\
         # Personality tests #\n\
         hint \"lots of play creates cheerful personality\"\n\
         test\n\
         let playful = do(init, [\n\
         Play, Play, Play, Play, Play,\n\
         Feed, Sleep\n\
         ]) in\n\
         playful.personality == Cheerful\n\
         end;\n\n\
         # Stat clamping tests #\n\
         hint \"stats cannot go below 0\"\n\
         test\n\
         let dying = (\n\
         stats = (hunger = 5, happiness = 5, energy = 5, health = 5),\n\
         evolution = Wilted,\n\
         personality = Grumpy,\n\
         memory = init.memory,\n\
         age = 30\n\
         ) in\n\
         let m = do(dying, timePasses(5)) in\n\
         m.stats.hunger >= 0 && m.stats.happiness >= 0 &&\n\
         m.stats.energy >= 0 && m.stats.health >= 0\n\
         end;\n\n\
         hint \"stats cannot exceed 100\"\n\
         test\n\
         let healthy = (\n\
         stats = (hunger = 90, happiness = 90, energy = 90, health = 95),\n\
         evolution = Elder,\n\
         personality = Cheerful,\n\
         memory = (timesFed = 10, timesPlayed = 10, timesSlept = 10, \
         timesNeglected = 0),\n\
         age = 30\n\
         ) in\n\
         let m = do(healthy, [Feed, Sleep]) in\n\
         m.stats.hunger <= 100 && m.stats.energy <= 100 && m.stats.health <= 100\n\
         end;\n\n\
         # Personality affects stats tests #\n\
         hint \"cheerful personality gives bonus to actions\"\n\
         test\n\
         let cheerfulModel = (\n\
         stats = (hunger = 50, happiness = 50, energy = 50, health = 50),\n\
         evolution = Bloom,\n\
         personality = Cheerful,\n\
         memory = init.memory,\n\
         age = 25\n\
         ) in\n\
         let grumpyModel = (\n\
         stats = (hunger = 50, happiness = 50, energy = 50, health = 50),\n\
         evolution = Bloom,\n\
         personality = Grumpy,\n\
         memory = init.memory,\n\
         age = 25\n\
         ) in\n\
         let cheerfulFed = update(cheerfulModel, Feed) in\n\
         let grumpyFed = update(grumpyModel, Feed) in\n\
         cheerfulFed.stats.hunger > grumpyFed.stats.hunger\n\
         end;\n\n\
         # Complex scenario tests #\n\
         hint \"daily routine maintains health\"\n\
         test\n\
         let dailyRoutine = [Feed, Play, Sleep, TimeTick, TimeTick] in\n\
         let m = do(init, dailyRoutine) in\n\
         m.stats.health >= init.stats.health - 5\n\
         end;\n\n\
         hint \"neglect leads to wilted evolution\"\n\
         test\n\
         # Just let time pass without care #\n\
         let neglected = do(init, timePasses(30)) in\n\
         neglected.evolution == Wilted\n\
         end;\n\n\
         hint \"age increases with time ticks\"\n\
         test\n\
         let m = do(init, timePasses(5)) in\n\
         m.age == 5\n\
         end;\n\n\
         hint \"age does not increase with other actions\"\n\
         test\n\
         let m = do(init, [Feed, Play, Sleep, Mend]) in\n\
         m.age == 0\n\
         end;\n\n\
         # Final demo: simulate a week of care #\n\
         do(init, [\n\
         # Day 1 #\n\
         Feed, Play, Sleep, TimeTick, TimeTick,\n\
         # Day 2 #\n\
         Feed, Play, TimeTick, TimeTick,\n\
         # Day 3 #\n\
         Feed, Sleep, TimeTick, TimeTick,\n\
         # Day 4 #\n\
         Feed, Play, Play, Sleep, TimeTick, TimeTick,\n\
         # Day 5 #\n\
         Feed, Mend, Sleep, TimeTick, TimeTick\n\
         ])\n";
      refractors = "()";
    } )
